export const mechanisms:ProductMechanism[]=[
 {id:'exposure',label:{en:'Repeated exposure',ro:'Expunere repetată'},short:{en:'Encountering the same claim again.',ro:'Reîntâlnirea aceleiași afirmații.'},what:{en:'A repeated encounter with the same or highly similar information.',ro:'O nouă întâlnire cu aceeași informație sau cu una foarte asemănătoare.'},why:{en:'Repetition is experimentally manipulable and is the entry point of the illusory-truth phenomenon.',ro:'Repetarea poate fi manipulată experimental și este punctul de intrare al fenomenului de adevăr iluzoriu.'},influencedBy:[{en:'Media frequency, recommendation, repeated messages and prior encounters',ro:'Frecvență media, recomandare, mesaje repetate și întâlniri anterioare'}],influences:[{en:'Familiarity, accessibility and later truth judgments',ro:'Familiaritatea, accesibilitatea și judecățile ulterioare de adevăr'}],evidence:{en:'Controlled experiments consistently show higher judged truth for previously seen than novel claims on average.',ro:'Experimentele controlate arată în mod consistent, în medie, evaluări de adevăr mai mari pentru afirmații văzute anterior decât pentru cele noi.'},effect:{en:'2026 synthesis: 182 studies, 366 effect sizes, 31,184 participants; bias-adjusted average g = 0.37, 95% CI 0.30–0.44.',ro:'Sinteza 2026: 182 studii, 366 mărimi ale efectului, 31.184 participanți; media ajustată pentru bias g = 0,37, IC 95% 0,30–0,44.'},conditions:{en:'Item type, first-exposure instructions, veracity cues and presentation duration explain part of the heterogeneity.',ro:'Tipul afirmației, instrucțiunile la prima expunere, indiciile de veridicitate și durata prezentării explică o parte din eterogenitate.'},competing:{en:'Repetition can alter familiarity, processing fluency, accessibility and source memory; the pooled endpoint does not isolate one universal mediator.',ro:'Repetarea poate modifica familiaritatea, fluența procesării, accesibilitatea și memoria sursei; rezultatul agregat nu izolează un mediator universal.'},limitations:{en:'Repetition is not evidence and does not persuade everyone or generalize equally across domains.',ro:'Repetarea nu este dovadă și nu convinge pe toată lumea sau în aceeași măsură în toate domeniile.'},interventions:{en:'Veracity cues, warnings and accuracy-focused prompts can alter downstream evaluation or sharing.',ro:'Indiciile de veridicitate, avertismentele și prompturile orientate spre acuratețe pot modifica evaluarea sau distribuirea ulterioară.'},theorySlug:'repetition-familiarity-truth',sources:[src.truth2026]},
 {id:'familiarity',label:{en:'Familiarity',ro:'Familiaritate'},short:{en:'How familiar information feels after prior exposure.',ro:'Cât de familiară pare informația după expuneri anterioare.'},what:{en:'A subjective memory signal that information has been encountered before; it is not evidence that the information is true.',ro:'Un semnal subiectiv de memorie că informația a mai fost întâlnită; nu este dovadă că informația este adevărată.'},why:{en:'CEM uses familiarity as a minimal internal bridge between exposure history and later judgment.',ro:'CEM folosește familiaritatea ca punte internă minimă între istoricul expunerii și judecata ulterioară.'},influencedBy:[{en:'Prior encounters and retrieval conditions',ro:'Întâlniri anterioare și condiții de reactualizare'}],influences:[{en:'Perceived plausibility and belief-related judgment',ro:'Plauzibilitatea percepută și judecata asociată credinței'}],evidence:{en:'Familiarity and processing fluency are prominent explanations of illusory truth, while the strongest synthesis estimates the endpoint repetition effect rather than a mediator coefficient.',ro:'Familiaritatea și fluența procesării sunt explicații importante ale adevărului iluzoriu, în timp ce cea mai puternică sinteză estimează efectul final al repetării, nu un coeficient al mediatorului.'},conditions:{en:'Knowledge, context and source/veracity cues can constrain how familiarity is used.',ro:'Cunoașterea, contextul și indiciile despre sursă/veridicitate pot limita modul în care este folosită familiaritatea.'},competing:{en:'Processing fluency, accessibility and source-memory processes overlap with familiarity accounts.',ro:'Fluența procesării, accesibilitatea și procesele de memorie a sursei se suprapun cu explicațiile bazate pe familiaritate.'},limitations:{en:'CEM does not infer an individual’s belief from familiarity alone.',ro:'CEM nu deduce credința unui individ numai din familiaritate.'},interventions:{en:'Corrections and veracity cues target later interpretation; they need not remove familiarity itself.',ro:'Corecțiile și indiciile de veridicitate vizează interpretarea ulterioară; nu trebuie să elimine familiaritatea însăși.'},theorySlug:'repetition-familiarity-truth',sources:[src.truth2026]},
 {id:'source',label:{en:'Source and credibility cues',ro:'Sursă și indicii de credibilitate'},short:{en:'Who information comes from and what is known about that source.',ro:'De la cine provine informația și ce se știe despre acea sursă.'},what:{en:'Provenance and cues used to estimate a source’s expertise, reliability or trustworthiness.',ro:'Proveniența și indiciile folosite pentru estimarea expertizei, fiabilității sau încrederii într-o sursă.'},why:{en:'Source information can change how the same claim is interpreted, but credibility is not a truth certificate.',ro:'Informația despre sursă poate schimba interpretarea aceleiași afirmații, dar credibilitatea nu este certificat de adevăr.'},influencedBy:[{en:'Prior experience, reputation, expertise cues and feedback',ro:'Experiență anterioară, reputație, indicii de expertiză și feedback'}],influences:[{en:'Credibility appraisal, evidence weighting and later belief',ro:'Evaluarea credibilității, ponderarea dovezilor și credința ulterioară'}],evidence:{en:'Experiments show source reliability can alter belief updating, while a 3-week field experiment of credibility labels found limited average effects on real news consumption and misperceptions. Context and implementation therefore matter.',ro:'Experimentele arată că fiabilitatea sursei poate modifica actualizarea credințelor, în timp ce un experiment de teren de 3 săptămâni cu etichete de credibilitate a găsit efecte medii limitate asupra consumului real de știri și percepțiilor eronate. Contextul și implementarea contează.'},conditions:{en:'Effects depend on whether source information is noticed, diagnostic for the task and remembered.',ro:'Efectele depind de observarea informației despre sursă, relevanța ei pentru sarcină și reținerea ei în memorie.'},competing:{en:'People may respond to message content, prior beliefs or social identity rather than the source cue itself.',ro:'Oamenii pot răspunde conținutului mesajului, credințelor anterioare sau identității sociale, nu indiciului despre sursă în sine.'},limitations:{en:'High perceived credibility can be wrong; source reputation cannot substitute for claim-level evidence.',ro:'Credibilitatea percepută ridicată poate fi greșită; reputația sursei nu poate înlocui dovezile la nivelul afirmației.'},interventions:{en:'Source-credibility badges and lateral reading have been tested, with heterogeneous results across settings.',ro:'Badge-urile de credibilitate și lateral reading au fost testate, cu rezultate eterogene între contexte.'},theorySlug:'sources-feedback-reliability',sources:[src.sourceNorms,src.sourceField,src.sourceUpdate]},
 {id:'framing',label:{en:'Presentation and framing',ro:'Prezentare și framing'},short:{en:'How equivalent or similar information is presented.',ro:'Modul în care informații echivalente sau similare sunt prezentate.'},what:{en:'Features of presentation that change emphasis, reference point, valence or interpretation without necessarily changing the underlying facts.',ro:'Caracteristici ale prezentării care schimbă accentul, punctul de referință, valența sau interpretarea fără a schimba neapărat faptele de bază.'},why:{en:'Experimental framing manipulations can change judgments and choices, but effect sizes are domain- and task-dependent.',ro:'Manipulările experimentale de framing pot schimba judecăți și alegeri, dar mărimea efectelor depinde de domeniu și sarcină.'},influencedBy:[{en:'Message design, reference points, wording and congruence with prior attitudes',ro:'Designul mesajului, punctele de referință, formularea și congruența cu atitudinile anterioare'}],influences:[{en:'Attention, appraisal and judgment',ro:'Atenția, evaluarea și judecata'}],evidence:{en:'Large meta-analyses document framing effects in risky choice and moral judgment, while also showing substantial variability and publication-bias sensitivity.',ro:'Meta-analize ample documentează efecte de framing în alegeri riscante și judecăți morale, arătând totodată variabilitate substanțială și sensibilitate la publication bias.'},effect:{en:'In moral-judgment framing, 146 experiments (49,564 participants) yielded d = 0.50 in published between-subject designs; publication-bias adjustment attenuated this to d = 0.22. This does not generalize as a CEM-wide coefficient.',ro:'În framing-ul judecăților morale, 146 experimente (49.564 participanți) au produs d = 0,50 în designurile between-subject publicate; ajustarea pentru publication bias a redus estimarea la d = 0,22. Aceasta nu se generalizează ca un coeficient CEM universal.'},conditions:{en:'Task, domain, design, reference point and participant characteristics can moderate framing effects.',ro:'Sarcina, domeniul, designul, punctul de referință și caracteristicile participanților pot modera efectele de framing.'},competing:{en:'Apparent framing effects can involve comprehension, loss aversion, reference dependence or demand characteristics.',ro:'Efectele aparente de framing pot implica înțelegerea, aversiunea față de pierdere, dependența de punctul de referință sau demand characteristics.'},limitations:{en:'CEM has no universal framing coefficient and does not treat framing as falsity or manipulation by definition.',ro:'CEM nu are un coeficient universal de framing și nu tratează framing-ul drept falsitate sau manipulare prin definiție.'},interventions:{en:'Reframing and context disclosure can be studied, but CEM does not prescribe a preferred frame.',ro:'Reframing-ul și dezvăluirea contextului pot fi studiate, dar CEM nu prescrie un cadru preferat.'},theorySlug:'framing-congruence',sources:[src.framingRisk,src.framingMoral]},
 {id:'salience',label:{en:'Emotion and salience',ro:'Emoție și saliență'},short:{en:'Features that make information stand out or feel urgent.',ro:'Caracteristici care fac informația să iasă în evidență sau să pară urgentă.'},what:{en:'A bounded family of affective and attentional influences, not a single universal emotion variable.',ro:'O familie delimitată de influențe afective și atenționale, nu o singură variabilă universală de emoție.'},why:{en:'Emotion and salience can shape what is noticed and how it is appraised before judgment.',ro:'Emoția și saliența pot modela ceea ce este observat și modul în care este evaluat înaintea judecății.'},influencedBy:[{en:'Valence, arousal, vividness, urgency and message design',ro:'Valență, activare, vivacitate, urgență și designul mesajului'}],influences:[{en:'Attention, perceived relevance and downstream judgment',ro:'Atenția, relevanța percepută și judecata ulterioară'}],evidence:{en:'Experimental studies show emotional framing can change detection and sharing in specific misinformation tasks; health-misinformation work also finds negative emotional appeal associated with greater sharing intentions in tested conditions.',ro:'Studiile experimentale arată că framing-ul emoțional poate schimba detectarea și distribuirea în sarcini specifice de misinformation; cercetări pe misinformation de sănătate găsesc și că apelul emoțional negativ se asociază cu intenții mai mari de distribuire în condițiile testate.'},conditions:{en:'Effects are highly dependent on message type, topic, audience and outcome.',ro:'Efectele depind puternic de tipul mesajului, subiect, audiență și outcome.'},competing:{en:'Novelty, perceived importance, source cues and prior involvement can produce similar attention patterns.',ro:'Noutatea, importanța percepută, indiciile despre sursă și implicarea anterioară pot produce pattern-uri similare de atenție.'},limitations:{en:'CEM does not contain a validated general emotion-to-belief coefficient.',ro:'CEM nu conține un coeficient general validat emoție–credință.'},interventions:{en:'Accuracy nudges and interface design can redirect attention, but evidence should be interpreted within the tested context.',ro:'Accuracy nudges și designul interfeței pot redirecționa atenția, dar dovezile trebuie interpretate în contextul testat.'},theorySlug:'framing-congruence',sources:[src.emotionHealth]},
 {id:'attention',label:{en:'Attention and access',ro:'Atenție și acces'},short:{en:'Whether information is actually opened, noticed and available for processing.',ro:'Dacă informația este efectiv deschisă, observată și disponibilă procesării.'},what:{en:'The transition from information being available to being accessed and attended to enough for downstream processing.',ro:'Trecerea de la informația disponibilă la informația accesată și observată suficient pentru procesarea ulterioară.'},why:{en:'Availability does not guarantee attention, reading, encoding or comprehension.',ro:'Disponibilitatea nu garantează atenție, lectură, encodare sau înțelegere.'},influencedBy:[{en:'Presentation, salience, interface position, goals and competing information',ro:'Prezentare, saliență, poziție în interfață, obiective și informații concurente'}],influences:[{en:'What information reaches memory and appraisal',ro:'Ce informație ajunge în memorie și evaluare'}],evidence:{en:'CEM has executable access stages, but does not equate an impression or click with measured attention. Direct attentional claims require dedicated measurement.',ro:'CEM are etape executabile de acces, dar nu echivalează o impresie sau un click cu atenția măsurată. Afirmațiile directe despre atenție necesită măsurare dedicată.'},conditions:{en:'Task goals, device, interface and cognitive load can alter access and attention.',ro:'Obiectivele sarcinii, dispozitivul, interfața și încărcarea cognitivă pot modifica accesul și atenția.'},competing:{en:'Observed downstream effects may reflect selection or presentation before attention itself.',ro:'Efectele ulterioare observate pot reflecta selecția sau prezentarea înainte de atenția propriu-zisă.'},limitations:{en:'CEM cannot infer gaze, fixation or comprehension from exposure logs alone.',ro:'CEM nu poate deduce privirea, fixația sau înțelegerea numai din logurile de expunere.'},interventions:{en:'Friction, prompts and interface changes can alter access or attention, but their mechanisms differ.',ro:'Friction, prompturile și modificările de interfață pot schimba accesul sau atenția, dar mecanismele lor diferă.'},theorySlug:'algorithms-social-feedback',sources:[src.misinformationReview]},
 {id:'observed',label:{en:'Observed information',ro:'Informație observată'},short:{en:'The information sample that actually reaches downstream processing.',ro:'Eșantionul informațional care ajunge efectiv la procesarea ulterioară.'},what:{en:'The subset of available information that survives selection, presentation and access.',ro:'Submulțimea informației disponibile care trece prin selecție, prezentare și acces.'},why:{en:'CEM separates the world and available information from the sample a person actually encounters.',ro:'CEM separă lumea și informația disponibilă de eșantionul întâlnit efectiv de o persoană.'},influencedBy:[{en:'Selection, ranking, presentation and access',ro:'Selecție, ranking, prezentare și acces'}],influences:[{en:'Memory, appraisal and the internal representation',ro:'Memoria, evaluarea și reprezentarea internă'}],evidence:{en:'This separation is partly an executable bookkeeping relation and partly a conceptual boundary. It prevents the observed sample from being mistaken for reality itself.',ro:'Această separare este parțial o relație executabilă de contabilizare și parțial o limită conceptuală. Ea împiedică confundarea eșantionului observat cu realitatea însăși.'},conditions:{en:'The observed sample depends on the information environment and access process.',ro:'Eșantionul observat depinde de mediul informațional și procesul de acces.'},competing:{en:'No competing psychological mechanism is required to explain sampling; the main uncertainty is representativeness.',ro:'Nu este necesar un mecanism psihologic concurent pentru a explica eșantionarea; principala incertitudine este reprezentativitatea.'},limitations:{en:'Observed information is not ground truth and not the person’s opinion.',ro:'Informația observată nu este ground truth și nici opinia persoanei.'},interventions:{en:'Diversity and provenance tools may change the information sample but require separate empirical evaluation.',ro:'Instrumentele de diversitate și proveniență pot schimba eșantionul informațional, dar necesită evaluare empirică separată.'},theorySlug:'world-information-representation',sources:[]},
 {id:'memory',label:{en:'Memory and retrieval',ro:'Memorie și reactualizare'},short:{en:'What is retained, accessible and retrieved when a claim is evaluated again.',ro:'Ce este reținut, accesibil și reactualizat când o afirmație este evaluată din nou.'},what:{en:'Memory processes that retain claim content, corrective context and source information with different accessibility over time.',ro:'Procese de memorie care păstrează conținutul afirmației, contextul corectiv și informația despre sursă cu accesibilitate diferită în timp.'},why:{en:'Later judgments depend not only on what was once presented, but on what can be retrieved at the moment of evaluation.',ro:'Judecățile ulterioare depind nu doar de ce a fost prezentat cândva, ci de ceea ce poate fi reactualizat în momentul evaluării.'},influencedBy:[{en:'Encoding, repetition, delay, source memory and corrective information',ro:'Encodare, repetiție, întârziere, memoria sursei și informație corectivă'}],influences:[{en:'Priors, world-model revision and later belief judgment',ro:'Priors, revizuirea world model-ului și judecata ulterioară de credință'}],evidence:{en:'A 2024 review highlights retrieval of corrections, repeated exposure and source memory as key determinants of correction durability; correction effects can decline over time, especially when source information is not remembered.',ro:'Un review din 2024 evidențiază reactualizarea corecțiilor, expunerea repetată și memoria sursei ca determinanți importanți ai durabilității corecțiilor; efectele corecției pot scădea în timp, mai ales când informația despre sursă nu este reținută.'},conditions:{en:'Delay, repetition, integration of correction and source recollection matter.',ro:'Întârzierea, repetarea, integrarea corecției și reactualizarea sursei contează.'},competing:{en:'Storage, retrieval, source-monitoring and gist-based accounts can explain different memory errors.',ro:'Explicațiile bazate pe stocare, reactualizare, source monitoring și gist pot explica erori diferite de memorie.'},limitations:{en:'Memory is not a single scalar store and CEM cannot reconstruct an individual’s memory contents from exposure logs.',ro:'Memoria nu este un depozit scalar unic, iar CEM nu poate reconstrui conținutul memoriei unui individ din logurile de expunere.'},interventions:{en:'Clear corrective explanations and source cues may improve later retrieval, but durability varies.',ro:'Explicațiile corective clare și indiciile despre sursă pot îmbunătăți reactualizarea ulterioară, dar durabilitatea variază.'},theorySlug:'corrections-accessibility-memory',sources:[src.memoryCorrection,src.misinformationReview]},
 {id:'prior',label:{en:'Prior knowledge and beliefs',ro:'Cunoștințe și credințe anterioare'},short:{en:'What a person brings to the interpretation before the new information arrives.',ro:'Ceea ce aduce persoana în interpretare înaintea informației noi.'},what:{en:'Stored knowledge, expectations and prior beliefs that constrain interpretation and updating.',ro:'Cunoștințe stocate, așteptări și credințe anterioare care constrâng interpretarea și actualizarea.'},why:{en:'New information is rarely interpreted without context; prior knowledge can help or mislead depending on its accuracy and relevance.',ro:'Informația nouă este rareori interpretată fără context; cunoașterea anterioară poate ajuta sau induce în eroare în funcție de acuratețe și relevanță.'},influencedBy:[{en:'Learning, memory, previous evidence and social experience',ro:'Învățare, memorie, dovezi anterioare și experiență socială'}],influences:[{en:'World-model interpretation, uncertainty and belief updating',ro:'Interpretarea world model-ului, incertitudinea și actualizarea credințelor'}],evidence:{en:'Prior knowledge is a broad empirical construct; where CEM uses Bayesian language it is a normative analogy unless a task supplies a defensible probabilistic prior.',ro:'Cunoașterea anterioară este un construct empiric larg; acolo unde CEM folosește limbaj bayesian, acesta este o analogie normativă dacă sarcina nu oferă un prior probabilistic justificabil.'},conditions:{en:'Relevance, confidence, diagnostic evidence and task structure determine how useful prior knowledge is.',ro:'Relevanța, încrederea, dovezile diagnostice și structura sarcinii determină utilitatea cunoașterii anterioare.'},competing:{en:'Motivated reasoning, source cues and memory accessibility can resemble prior-driven updating.',ro:'Motivated reasoning, indiciile despre sursă și accesibilitatea memoriei pot semăna cu actualizarea condusă de priors.'},limitations:{en:'A psychological prior belief is not automatically a calibrated probability.',ro:'O credință psihologică anterioară nu este automat o probabilitate calibrată.'},interventions:{en:'Lateral reading and media literacy can change what evidence is gathered before updating.',ro:'Lateral reading și media literacy pot schimba dovezile colectate înainte de actualizare.'},theorySlug:'world-model-construction',sources:[src.predictiveReview]},
 {id:'world-model',label:{en:'Internal world model',ro:'Model intern al realității'},short:{en:'A working representation of how the relevant part of the world is believed to be structured.',ro:'O reprezentare de lucru a modului în care se crede că este structurat segmentul relevant al realității.'},what:{en:'A representational construct integrating observations, memory, priors, source information and uncertainty.',ro:'Un construct reprezentațional care integrează observații, memorie, priors, informația despre sursă și incertitudinea.'},why:{en:'It provides the context in which new information is interpreted and contradictions can trigger reassessment.',ro:'Oferă contextul în care informația nouă este interpretată, iar contradicțiile pot declanșa reevaluarea.'},influencedBy:[{en:'Observed information, prior knowledge, source cues and social context',ro:'Informație observată, cunoaștere anterioară, indicii despre sursă și context social'}],influences:[{en:'Expectations, uncertainty, appraisal and revision',ro:'Așteptări, incertitudine, evaluare și revizuire'}],evidence:{en:'Internal-model language is compatible with several cognitive frameworks. A 2026 predictive-processing review notes both supportive neurophysiological patterns and major definitional/evidential ambiguities, so CEM treats its world model as a representational construct rather than proof of one neural theory.',ro:'Limbajul modelului intern este compatibil cu mai multe cadre cognitive. Un review din 2026 al predictive processing notează atât pattern-uri neurofiziologice compatibile, cât și ambiguități majore de definiție și dovezi, astfel că CEM tratează world model-ul drept construct reprezentațional, nu dovadă a unei singure teorii neurale.'},conditions:{en:'Task, domain, available evidence and memory determine the granularity and stability of the representation.',ro:'Sarcina, domeniul, dovezile disponibile și memoria determină granularitatea și stabilitatea reprezentării.'},competing:{en:'Schema, situation-model, predictive-processing and Bayesian accounts overlap but are not equivalent.',ro:'Explicațiile bazate pe scheme, situation models, predictive processing și Bayes se suprapun, dar nu sunt echivalente.'},limitations:{en:'CEM does not reconstruct a person’s complete mental model and does not claim a neural implementation.',ro:'CEM nu reconstruiește modelul mental complet al unei persoane și nu afirmă o implementare neurală.'},interventions:{en:'Information-gathering and correction can supply inputs for revision; no intervention directly “edits” a world model.',ro:'Colectarea informației și corecția pot furniza intrări pentru revizuire; nicio intervenție nu „editează” direct un world model.'},theorySlug:'world-model-construction',sources:[src.predictiveReview]},
 {id:'uncertainty',label:{en:'Uncertainty',ro:'Incertitudine'},short:{en:'What remains unresolved or weakly determined in the current interpretation.',ro:'Ceea ce rămâne nerezolvat sau slab determinat în interpretarea curentă.'},what:{en:'A representation of unresolved alternatives, missing information or weak diagnostic support.',ro:'O reprezentare a alternativelor nerezolvate, informației lipsă sau suportului diagnostic slab.'},why:{en:'Uncertainty affects whether a representation should be maintained, qualified or reassessed.',ro:'Incertitudinea influențează dacă o reprezentare trebuie menținută, nuanțată sau reevaluată.'},influencedBy:[{en:'Conflicting evidence, source reliability, missing information and prior certainty',ro:'Dovezi conflictuale, fiabilitatea sursei, informația lipsă și certitudinea anterioară'}],influences:[{en:'Appraisal, information seeking and reassessment',ro:'Evaluarea, căutarea informației și reevaluarea'}],evidence:{en:'CEM keeps descriptive psychological uncertainty distinct from calibrated probability unless the task provides a defensible probabilistic interpretation.',ro:'CEM păstrează incertitudinea psihologică descriptivă distinctă de probabilitatea calibrată dacă sarcina nu oferă o interpretare probabilistică justificabilă.'},conditions:{en:'Consequences, time pressure, available alternatives and metacognitive sensitivity matter.',ro:'Consecințele, presiunea timpului, alternativele disponibile și sensibilitatea metacognitivă contează.'},competing:{en:'Low confidence, ambiguity and lack of knowledge are related but not identical constructs.',ro:'Încrederea redusă, ambiguitatea și lipsa cunoașterii sunt constructe înrudite, dar nu identice.'},limitations:{en:'CEM does not convert every uncertainty judgment into a numeric probability.',ro:'CEM nu transformă orice judecată de incertitudine într-o probabilitate numerică.'},interventions:{en:'Lateral reading, evidence gathering and explicit uncertainty communication can change the information available for reassessment.',ro:'Lateral reading, colectarea dovezilor și comunicarea explicită a incertitudinii pot schimba informația disponibilă pentru reevaluare.'},theorySlug:'uncertainty-closure',sources:[src.predictiveReview]},
 {id:'appraisal',label:{en:'Appraisal and plausibility',ro:'Evaluare și plauzibilitate'},short:{en:'How the information is interpreted relative to evidence, context and prior knowledge.',ro:'Cum este interpretată informația în raport cu dovezile, contextul și cunoașterea anterioară.'},what:{en:'A task-dependent evaluation of relevance, credibility, plausibility or diagnostic value before a final judgment.',ro:'O evaluare dependentă de sarcină a relevanței, credibilității, plauzibilității sau valorii diagnostice înaintea unei judecăți finale.'},why:{en:'It is where source cues, framing, familiarity, priors and uncertainty can converge without being collapsed into one variable.',ro:'Este punctul în care indiciile despre sursă, framing-ul, familiaritatea, priors și incertitudinea pot converge fără a fi reduse la o singură variabilă.'},influencedBy:[{en:'Source, framing, familiarity, priors, evidence and uncertainty',ro:'Sursă, framing, familiaritate, priors, dovezi și incertitudine'}],influences:[{en:'Belief and judgment',ro:'Credința și judecata'}],evidence:{en:'CEM treats appraisal as an organizing construct. Individual inputs have varying empirical support, so no universal appraisal equation is claimed.',ro:'CEM tratează evaluarea ca pe un construct organizatoric. Intrările individuale au suport empiric variabil, deci nu este afirmată o ecuație universală a evaluării.'},conditions:{en:'The meaning of appraisal depends on the task and outcome being judged.',ro:'Sensul evaluării depinde de sarcină și de outcome-ul judecat.'},competing:{en:'Heuristic processing, deliberation and task-specific decision rules can generate similar observed judgments.',ro:'Procesarea euristică, deliberarea și regulile de decizie specifice sarcinii pot genera judecăți observate similare.'},limitations:{en:'Appraisal is not a hidden “truth detector”.',ro:'Evaluarea nu este un „detector de adevăr” ascuns.'},interventions:{en:'Prompts, warnings and literacy interventions can change inputs or decision criteria rather than appraisal in one uniform way.',ro:'Prompturile, avertismentele și intervențiile de literacy pot schimba intrările sau criteriile de decizie, nu evaluarea într-un mod uniform.'},theorySlug:'world-information-representation',sources:[src.newsJudgment]},
 {id:'correction',label:{en:'Correction',ro:'Corecție'},short:{en:'Information that explicitly challenges or replaces a prior false or unsupported claim.',ro:'Informație care contestă sau înlocuiește explicit o afirmație anterioară falsă sau nesusținută.'},what:{en:'A reactive intervention that supplies corrective information after misinformation has been encountered.',ro:'O intervenție reactivă care furnizează informație corectivă după întâlnirea cu misinformation.'},why:{en:'Corrections can update belief and memory, but misinformation can retain a continued influence on reasoning.',ro:'Corecțiile pot actualiza credința și memoria, dar misinformation poate păstra o influență continuă asupra raționamentului.'},influencedBy:[{en:'Correction quality, explanation, timing, source and prior misinformation memory',ro:'Calitatea corecției, explicația, timing-ul, sursa și memoria misinformation anterioare'}],influences:[{en:'Memory retrieval, reassessment and belief updating',ro:'Reactualizarea memoriei, reevaluarea și actualizarea credinței'}],evidence:{en:'Major reviews conclude that debunking can reduce misinformation effects but is not universally complete or durable; memory for the correction and its source matters over time.',ro:'Review-uri importante concluzionează că debunking-ul poate reduce efectele misinformation, dar nu este universal complet sau durabil; memoria corecției și a sursei sale contează în timp.'},conditions:{en:'Delay, repetition, source memory, explanation quality and domain can change correction efficacy.',ro:'Întârzierea, repetarea, memoria sursei, calitatea explicației și domeniul pot schimba eficacitatea corecției.'},competing:{en:'Residual effects may reflect retrieval competition, integration failure or continued accessibility rather than “backfire”.',ro:'Efectele reziduale pot reflecta competiția la reactualizare, eșecul integrării sau accesibilitatea continuă, nu neapărat „backfire”.'},limitations:{en:'A correction does not guarantee belief reversal or memory erasure.',ro:'O corecție nu garantează inversarea credinței sau ștergerea memoriei.'},interventions:{en:'Debunking/rebuttal and warning labels are reactive approaches; prebunking/inoculation is pre-emptive.',ro:'Debunking/rebuttal și warning labels sunt abordări reactive; prebunking/inoculation este preventivă.'},theorySlug:'corrections-accessibility-memory',sources:[src.misinformationReview,src.memoryCorrection]},
 {id:'reassessment',label:{en:'Reassessment',ro:'Reevaluare'},short:{en:'Reopening an interpretation when new or conflicting information arrives.',ro:'Redeschiderea unei interpretări când apare informație nouă sau conflictuală.'},what:{en:'A revision process in which the current representation is compared with new evidence, remembered context and alternatives.',ro:'Un proces de revizuire în care reprezentarea curentă este comparată cu dovezi noi, context memorat și alternative.'},why:{en:'It prevents CEM from treating beliefs as one-way accumulations that can only increase.',ro:'Împiedică CEM să trateze credințele ca acumulări unidirecționale care pot doar crește.'},influencedBy:[{en:'Corrections, contradictions, uncertainty and new observations',ro:'Corecții, contradicții, incertitudine și observații noi'}],influences:[{en:'Updated memory, world model and later judgment',ro:'Memoria actualizată, world model-ul și judecata ulterioară'}],evidence:{en:'Reassessment is a conceptual/executable bridge across correction and world-model modules; its exact human implementation is not uniquely identified.',ro:'Reevaluarea este o punte conceptuală/executabilă între modulele de corecție și world model; implementarea umană exactă nu este identificată unic.'},conditions:{en:'Motivation, available evidence, memory and uncertainty can affect whether reassessment occurs.',ro:'Motivația, dovezile disponibile, memoria și incertitudinea pot afecta apariția reevaluării.'},competing:{en:'Simple response change, forgetting or demand effects can mimic revision in some experiments.',ro:'Schimbarea simplă a răspunsului, uitarea sau demand effects pot imita revizuirea în unele experimente.'},limitations:{en:'CEM does not claim every contradiction triggers deliberative reconsideration.',ro:'CEM nu afirmă că orice contradicție declanșează reconsiderare deliberativă.'},interventions:{en:'Corrections, lateral reading and evidence prompts can supply triggers or material for reassessment.',ro:'Corecțiile, lateral reading și prompturile de dovezi pot furniza declanșatori sau material pentru reevaluare.'},theorySlug:'world-model-construction',sources:[src.misinformationReview]},
 {id:'belief',label:{en:'Belief judgment',ro:'Judecată de credință'},short:{en:'How plausible or true a claim is judged to be.',ro:'Cât de plauzibilă sau adevărată este considerată afirmația.'},what:{en:'A judgment about a claim produced from multiple inputs rather than a direct readout of truth.',ro:'O judecată despre o afirmație produsă din mai multe intrări, nu o citire directă a adevărului.'},why:{en:'CEM separates internal belief judgment from external truth and from later action.',ro:'CEM separă judecata internă de credință de adevărul extern și de acțiunea ulterioară.'},influencedBy:[{en:'Familiarity, priors, evidence, source context, framing and correction',ro:'Familiaritate, priors, dovezi, contextul sursei, framing și corecție'}],influences:[{en:'Judgment, decisions and some sharing tendencies',ro:'Judecata, deciziile și unele tendințe de distribuire'}],evidence:{en:'A 2025 systematic review/meta-analysis of news judgments synthesized 303 effect sizes from 67 experimental articles and 194,438 participants across 40 countries, illustrating both discernment and substantial variation in truth judgments.',ro:'O revizuire sistematică/meta-analiză din 2025 a sintetizat 303 mărimi ale efectului din 67 articole experimentale și 194.438 participanți din 40 de țări, ilustrând atât discernământul, cât și variația substanțială a judecăților de adevăr.'},conditions:{en:'Content, prior knowledge, source and task structure influence judgment.',ro:'Conținutul, cunoașterea anterioară, sursa și structura sarcinii influențează judecata.'},competing:{en:'Ratings can reflect recognition, response criteria or task demand as well as stable belief.',ro:'Evaluările pot reflecta recunoașterea, criteriile de răspuns sau cerințele sarcinii, nu doar o credință stabilă.'},limitations:{en:'CEM does not infer ideology, intelligence, intention or stable personal traits from belief ratings.',ro:'CEM nu deduce ideologie, inteligență, intenție sau trăsături personale stabile din evaluările de credință.'},interventions:{en:'Warnings, corrections, inoculation and literacy interventions can change belief or discernment in tested settings.',ro:'Avertismentele, corecțiile, inoculation și intervențiile de literacy pot schimba credința sau discernământul în contexte testate.'},theorySlug:'belief-accuracy-action',sources:[src.newsJudgment]},
 {id:'judgment',label:{en:'Judgment and decision',ro:'Judecată și decizie'},short:{en:'Turning an interpretation into a task-specific decision.',ro:'Transformarea unei interpretări într-o decizie specifică sarcinii.'},what:{en:'The point at which evidence, belief, uncertainty and goals are converted into a choice or reported evaluation.',ro:'Punctul în care dovezile, credința, incertitudinea și obiectivele sunt transformate într-o alegere sau evaluare raportată.'},why:{en:'The same internal belief can lead to different decisions when goals, incentives or uncertainty differ.',ro:'Aceeași credință internă poate conduce la decizii diferite când obiectivele, stimulentele sau incertitudinea diferă.'},influencedBy:[{en:'Belief, uncertainty, goals, social context and decision criteria',ro:'Credință, incertitudine, obiective, context social și criterii de decizie'}],influences:[{en:'Action, sharing or information seeking',ro:'Acțiune, distribuire sau căutarea informației'}],evidence:{en:'Judgment is task-specific; CEM therefore avoids treating every reported rating or click as the same psychological outcome.',ro:'Judecata este specifică sarcinii; CEM evită astfel tratarea fiecărei evaluări raportate sau fiecărui click ca același outcome psihologic.'},conditions:{en:'Stakes, incentives, time pressure and response format matter.',ro:'Mizele, stimulentele, presiunea timpului și formatul răspunsului contează.'},competing:{en:'Observed choices can reflect strategic or social motives without a corresponding belief change.',ro:'Alegerile observate pot reflecta motive strategice sau sociale fără o schimbare corespunzătoare a credinței.'},limitations:{en:'A decision is not a transparent measurement of all underlying cognition.',ro:'O decizie nu este o măsurare transparentă a întregii cogniții subiacente.'},interventions:{en:'Friction and prompts can alter decision conditions without directly changing belief.',ro:'Friction și prompturile pot schimba condițiile deciziei fără a modifica direct credința.'},theorySlug:'belief-accuracy-action',sources:[src.accuracy]},
 {id:'accuracy-attention',label:{en:'Attention to accuracy',ro:'Atenție la acuratețe'},short:{en:'Whether accuracy is salient when a sharing decision is made.',ro:'Dacă acuratețea este salientă când este luată decizia de distribuire.'},what:{en:'A decision-context factor that makes truthfulness more relevant at the moment of sharing.',ro:'Un factor al contextului decizional care face veridicitatea mai relevantă în momentul distribuirii.'},why:{en:'People can distinguish true from false content better than their sharing choices sometimes imply; shifting attention can improve sharing discernment.',ro:'Oamenii pot distinge conținutul adevărat de cel fals mai bine decât sugerează uneori alegerile lor de distribuire; redirecționarea atenției poate îmbunătăți discernământul la distribuire.'},influencedBy:[{en:'Prompts, task goals and interface cues',ro:'Prompturi, obiectivele sarcinii și indicii de interfață'}],influences:[{en:'Sharing discernment',ro:'Discernământul la distribuire'}],evidence:{en:'An internal meta-analysis of 20 experiments with 26,863 participants found accuracy prompts improved sharing discernment, mainly through about a 10% reduction in intentions to share false headlines.',ro:'O meta-analiză internă a 20 de experimente cu 26.863 participanți a găsit că accuracy prompts au îmbunătățit discernământul la distribuire, în principal printr-o reducere de aproximativ 10% a intenției de a distribui titluri false.'},effect:{en:'20 experiments, N = 26,863; false-headline sharing intentions decreased by about 10% relative to control in the analyzed studies.',ro:'20 experimente, N = 26.863; intenția de distribuire a titlurilor false a scăzut cu aproximativ 10% față de control în studiile analizate.'},conditions:{en:'Effects were larger among older, more reflective and more attentive participants; sharing-discernment heterogeneity was substantial.',ro:'Efectele au fost mai mari la participanți mai vârstnici, mai reflexivi și mai atenți; eterogenitatea discernământului la distribuire a fost substanțială.'},competing:{en:'Prompts may alter demand, caution or response thresholds as well as accuracy attention.',ro:'Prompturile pot modifica demand, prudența sau pragurile de răspuns, nu doar atenția la acuratețe.'},limitations:{en:'The synthesis is an internal meta-analysis from one research programme and focuses largely on U.S. online samples.',ro:'Sinteza este o meta-analiză internă dintr-un singur program de cercetare și se concentrează în mare parte pe eșantioane online din SUA.'},interventions:{en:'Accuracy prompts directly target this decision context.',ro:'Accuracy prompts vizează direct acest context decizional.'},theorySlug:'belief-accuracy-action',sources:[src.accuracy]},
 {id:'social',label:{en:'Social context and norms',ro:'Context social și norme'},short:{en:'What others appear to believe or do, and what behavior is socially approved.',ro:'Ce par să creadă sau să facă ceilalți și ce comportament este aprobat social.'},what:{en:'Descriptive norms, injunctive norms, apparent consensus, identity cues and social incentives surrounding information.',ro:'Norme descriptive, norme injunctive, consens aparent, indicii identitare și stimulente sociale din jurul informației.'},why:{en:'Social cues can influence interpretation and sharing, but apparent consensus is not independent evidence by default.',ro:'Indiciile sociale pot influența interpretarea și distribuirea, dar consensul aparent nu este implicit dovadă independentă.'},influencedBy:[{en:'Visible engagement, group identity, norms and platform design',ro:'Engagement vizibil, identitate de grup, norme și designul platformei'}],influences:[{en:'Appraisal, perceived consensus, judgment and sharing',ro:'Evaluare, consens perceput, judecată și distribuire'}],evidence:{en:'A 2024 social-media simulation experiment with 415 participants found both credibility badges and combined descriptive/injunctive social norms improved truth discernment; some engagement effects were not robust to alternative specifications.',ro:'Un experiment de simulare social media din 2024 cu 415 participanți a găsit că atât badge-urile de credibilitate, cât și normele sociale descriptive/injunctive au îmbunătățit discernământul; unele efecte asupra engagement-ului nu au fost robuste la specificații alternative.'},conditions:{en:'Group identity, perceived consensus independence, topic and platform context can moderate social influence.',ro:'Identitatea de grup, independența percepută a consensului, subiectul și contextul platformei pot modera influența socială.'},competing:{en:'Social proof can correlate with content quality, popularity or algorithmic exposure, making causal interpretation difficult outside experiments.',ro:'Social proof se poate corela cu calitatea conținutului, popularitatea sau expunerea algoritmică, complicând interpretarea cauzală în afara experimentelor.'},limitations:{en:'CEM does not equate popularity, consensus or group agreement with truth.',ro:'CEM nu echivalează popularitatea, consensul sau acordul de grup cu adevărul.'},interventions:{en:'Social-norm messages and credibility badges have experimental evidence but should be treated as context-dependent interventions.',ro:'Mesajele cu norme sociale și badge-urile de credibilitate au dovezi experimentale, dar trebuie tratate ca intervenții dependente de context.'},theorySlug:'algorithms-social-feedback',sources:[src.sourceNorms]},
 {id:'action',label:{en:'Sharing and action',ro:'Distribuire și acțiune'},short:{en:'What a person chooses to do with the information.',ro:'Ce alege o persoană să facă cu informația.'},what:{en:'A downstream behavior or intention such as sharing, clicking, seeking more information or acting on a judgment.',ro:'Un comportament sau o intenție ulterioară precum distribuirea, click-ul, căutarea de informații sau acțiunea pe baza unei judecăți.'},why:{en:'Action must remain separate from belief because social motives, incentives and attention can change behavior without equivalent belief change.',ro:'Acțiunea trebuie păstrată separat de credință deoarece motivele sociale, stimulentele și atenția pot schimba comportamentul fără o schimbare echivalentă a credinței.'},influencedBy:[{en:'Judgment, accuracy attention, social norms, incentives and friction',ro:'Judecată, atenția la acuratețe, norme sociale, stimulente și friction'}],influences:[{en:'Further exposure for other people and downstream real-world consequences',ro:'Expunere ulterioară pentru alte persoane și consecințe în lumea reală'}],evidence:{en:'Sharing discernment is experimentally modifiable by accuracy prompts, warning labels and some social-norm interventions, supporting the separation of action from belief.',ro:'Discernământul la distribuire poate fi modificat experimental prin accuracy prompts, warning labels și unele intervenții cu norme sociale, susținând separarea acțiunii de credință.'},conditions:{en:'Platform affordances, identity, incentives, topic and audience matter.',ro:'Funcțiile platformei, identitatea, stimulentele, subiectul și audiența contează.'},competing:{en:'Sharing can signal humour, identity, outrage, coordination or affiliation rather than endorsement.',ro:'Distribuirea poate semnala umor, identitate, indignare, coordonare sau afiliere, nu aprobare.'},limitations:{en:'Sharing is not proof of belief, ideology or intention beyond the observed action.',ro:'Distribuirea nu dovedește credința, ideologia sau intenția dincolo de acțiunea observată.'},interventions:{en:'Accuracy prompts, warnings, friction, norms and literacy interventions target different points before action.',ro:'Accuracy prompts, avertismentele, friction, normele și intervențiile de literacy vizează puncte diferite înaintea acțiunii.'},theorySlug:'belief-accuracy-action',sources:[src.accuracy,src.warning,src.sourceNorms]},
];

const e=(status:RelationStatus,en:string,ro:string):PathEdge=>({status,note:{en,ro}});
export const pathways:ProductPathway[]=[
 {id:'repetition',group:'updating',question:{en:'How can repeating a claim make it seem more true?',ro:'Cum poate repetarea unei afirmații să o facă să pară mai adevărată?'},title:{en:'Repetition → familiarity → belief → action',ro:'Repetiție → familiaritate → credință → acțiune'},intro:{en:'Follow the shortest evidence-grounded CEM path without treating repetition as evidence.',ro:'Urmărește cel mai scurt traseu CEM susținut de dovezi fără a trata repetarea drept dovadă.'},mechanismIds:['exposure','familiarity','belief','action'],edges:[e('EMPIRICAL_ASSOCIATION','Repetition reliably changes judged truth; familiarity is a prominent but not uniquely identified mediator.','Repetarea modifică în mod robust adevărul perceput; familiaritatea este un mediator important, dar nu identificat unic.'),e('EXECUTABLE_MODEL_RELATION','The reference model lets familiarity contribute to belief judgment; the coefficient is not meta-analytically calibrated.','Modelul de referință permite familiarității să contribuie la judecata de credință; coeficientul nu este calibrat meta-analitic.'),e('EXECUTABLE_MODEL_RELATION','The reference model links belief-related state to sharing while keeping action distinct from belief.','Modelul de referință leagă starea asociată credinței de distribuire, păstrând acțiunea distinctă de credință.')],secondary:[{label:{en:'Prior knowledge',ro:'Cunoaștere anterioară'},text:{en:'Can constrain how repeated information is interpreted.',ro:'Poate limita interpretarea informației repetate.'}},{label:{en:'Veracity cues',ro:'Indicii de veridicitate'},text:{en:'Can change later evaluation of familiar information.',ro:'Pot schimba evaluarea ulterioară a informației familiare.'}},{label:{en:'Source context',ro:'Contextul sursei'},text:{en:'Can alter appraisal without certifying truth.',ro:'Poate modifica evaluarea fără a certifica adevărul.'}},{label:{en:'Correction',ro:'Corecție'},text:{en:'Can compete with familiar misinformation during later retrieval.',ro:'Poate concura cu misinformation familiară la reactualizare.'}}],strongest:{en:'A 2026 meta-analysis synthesized 182 studies, 366 effect sizes and 31,184 participants; the bias-adjusted average illusory-truth effect was g = 0.37.',ro:'O meta-analiză din 2026 a sintetizat 182 studii, 366 mărimi ale efectului și 31.184 participanți; efectul mediu ajustat de adevăr iluzoriu a fost g = 0,37.'},uncertainty:{en:'The endpoint is robust but the exact causal mediation through familiarity/fluency is not a universal fixed chain.',ro:'Rezultatul final este robust, dar medierea cauzală exactă prin familiaritate/fluență nu este un lanț universal fix.'},moderators:{en:'Item type, first-exposure instructions, veracity cues and presentation duration.',ro:'Tipul afirmației, instrucțiunile la prima expunere, indiciile de veridicitate și durata prezentării.'},cannot:{en:'Repetition does not make a claim true, does not persuade everyone and does not generalize automatically to social-political opinion statements.',ro:'Repetarea nu face o afirmație adevărată, nu convinge pe toată lumea și nu se generalizează automat la opinii socio-politice.'},interventionIds:['accuracy','warning','debunking'],theorySlugs:['repetition-familiarity-truth','belief-accuracy-action']},
 {id:'source-credibility',group:'input',question:{en:'How does the source influence credibility?',ro:'Cum influențează sursa credibilitatea?'},title:{en:'Source cues → appraisal → belief → action',ro:'Indicii despre sursă → evaluare → credință → acțiune'},intro:{en:'Separate who said it from whether the claim is actually supported.',ro:'Separă cine a spus ceva de întrebarea dacă afirmația este efectiv susținută.'},mechanismIds:['source','appraisal','belief','action'],edges:[e('EMPIRICAL_CAUSAL_SUPPORT','Randomized source-credibility manipulations can change appraisal and belief updating in tested tasks.','Manipulările randomizate ale credibilității sursei pot schimba evaluarea și actualizarea credinței în sarcinile testate.'),e('EMPIRICAL_ASSOCIATION','Appraisal and belief are closely linked, but task measures do not identify one universal conversion.','Evaluarea și credința sunt strâns legate, dar măsurile de sarcină nu identifică o conversie universală.'),e('EXECUTABLE_MODEL_RELATION','CEM keeps belief and downstream action separate.','CEM păstrează separat credința și acțiunea ulterioară.')],secondary:[{label:{en:'Prior source experience',ro:'Experiență anterioară cu sursa'},text:{en:'Learning about a source can change later reliability estimates.',ro:'Învățarea despre o sursă poate schimba estimările ulterioare de fiabilitate.'}},{label:{en:'Message evidence',ro:'Dovezile mesajului'},text:{en:'Strong claim-level evidence can conflict with source reputation.',ro:'Dovezile puternice la nivelul afirmației pot intra în conflict cu reputația sursei.'}},{label:{en:'Social identity',ro:'Identitate socială'},text:{en:'Group alignment can alter how a source cue is interpreted.',ro:'Alinierea de grup poate modifica interpretarea unui indiciu despre sursă.'}}],strongest:{en:'Experiments support source-reliability effects on belief updating, while credibility-badge interventions show positive effects in some simulations and limited average effects in a multi-week field setting.',ro:'Experimentele susțin efecte ale fiabilității sursei asupra actualizării credințelor, în timp ce intervențiile cu badge-uri de credibilitate au efecte pozitive în unele simulări și efecte medii limitate într-un studiu de teren pe mai multe săptămâni.'},uncertainty:{en:'The effect of source cues depends strongly on implementation, attention to the cue and the relationship between source reputation and claim quality.',ro:'Efectul indiciilor despre sursă depinde puternic de implementare, atenția acordată indiciului și relația dintre reputația sursei și calitatea afirmației.'},moderators:{en:'Prior source experience, expertise/trustworthiness cues, topic and whether the cue is remembered.',ro:'Experiența anterioară cu sursa, indicii de expertiză/încredere, subiectul și reținerea indiciului.'},cannot:{en:'A credible source is not a truth certificate, and a low-credibility source does not make every claim false.',ro:'O sursă credibilă nu este certificat de adevăr, iar o sursă cu credibilitate redusă nu face toate afirmațiile false.'},interventionIds:['source-labels','lateral-reading','media-literacy'],theorySlugs:['sources-feedback-reliability']},
 {id:'framing',group:'input',question:{en:'How can framing change interpretation?',ro:'Cum poate framing-ul modifica interpretarea?'},title:{en:'Framing → attention → appraisal → judgment → action',ro:'Framing → atenție → evaluare → judecată → acțiune'},intro:{en:'Trace how presentation can change response without assuming it changes the underlying facts.',ro:'Urmărește modul în care prezentarea poate schimba răspunsul fără a presupune că schimbă faptele de bază.'},mechanismIds:['framing','attention','appraisal','judgment','action'],edges:[e('EMPIRICAL_ASSOCIATION','Presentation can alter what becomes salient or accessible, but attention is not directly measured in every framing study.','Prezentarea poate modifica ceea ce devine salient sau accesibil, dar atenția nu este măsurată direct în fiecare studiu de framing.'),e('CONCEPTUAL_HYPOTHESIS','CEM uses appraisal as a bridge between presentation/access and task-specific judgment; this is not a universal empirical equation.','CEM folosește evaluarea ca punte între prezentare/acces și judecata specifică sarcinii; nu este o ecuație empirică universală.'),e('EMPIRICAL_CAUSAL_SUPPORT','Randomized framing manipulations can change judgments and choices in multiple domains.','Manipulările randomizate de framing pot schimba judecăți și alegeri în multiple domenii.'),e('INTERPRETIVE_LINK','Judgment can lead to action, but goals and social context can alter the translation.','Judecata poate conduce la acțiune, dar obiectivele și contextul social pot modifica această traducere.')],secondary:[{label:{en:'Prior attitudes',ro:'Atitudini anterioare'},text:{en:'Congruence can change framing effects in task-specific ways.',ro:'Congruența poate schimba efectele de framing în moduri specifice sarcinii.'}},{label:{en:'Source',ro:'Sursă'},text:{en:'The same wording may be evaluated differently depending on provenance.',ro:'Aceeași formulare poate fi evaluată diferit în funcție de proveniență.'}},{label:{en:'Emotion',ro:'Emoție'},text:{en:'Valence and arousal can overlap with framing but are not identical to it.',ro:'Valența și activarea se pot suprapune cu framing-ul, dar nu sunt identice.'}}],strongest:{en:'Large meta-analyses show reproducible framing effects in risky choice and moral judgment, with substantial domain/design variation.',ro:'Meta-analize ample arată efecte reproductibile de framing în alegeri riscante și judecăți morale, cu variație substanțială după domeniu/design.'},uncertainty:{en:'No single framing coefficient transfers across tasks; publication bias and design choices affect pooled estimates.',ro:'Niciun coeficient unic de framing nu se transferă între sarcini; publication bias și alegerile de design afectează estimările agregate.'},moderators:{en:'Domain, reference point, wording, design and congruence with prior attitudes.',ro:'Domeniul, punctul de referință, formularea, designul și congruența cu atitudinile anterioare.'},cannot:{en:'Framing is not synonymous with falsehood, propaganda or manipulation.',ro:'Framing-ul nu este sinonim cu falsitatea, propaganda sau manipularea.'},interventionIds:['media-literacy','lateral-reading'],theorySlugs:['framing-congruence','world-information-representation']},
 {id:'emotion-salience',group:'input',question:{en:'How can emotion and salience influence attention and judgment?',ro:'Cum pot emoția și saliența influența atenția și judecata?'},title:{en:'Salience → attention → appraisal → judgment → action',ro:'Saliență → atenție → evaluare → judecată → acțiune'},intro:{en:'Treat emotion as a bounded context-dependent influence, not a universal persuasion variable.',ro:'Tratează emoția ca influență delimitată și dependentă de context, nu ca variabilă universală de persuasiune.'},mechanismIds:['salience','attention','appraisal','judgment','action'],edges:[e('EMPIRICAL_ASSOCIATION','Salient/emotional features can change attention and engagement, but the exact attentional mechanism varies by task.','Caracteristicile saliente/emoționale pot modifica atenția și engagement-ul, dar mecanismul atențional exact variază după sarcină.'),e('CONCEPTUAL_HYPOTHESIS','Appraisal organizes several task-dependent inputs without asserting one affect equation.','Evaluarea organizează mai multe intrări dependente de sarcină fără a afirma o ecuație unică a afectului.'),e('EMPIRICAL_CAUSAL_SUPPORT','Experimental message-framing studies show changes in detection/judgment in specific contexts.','Studiile experimentale de framing al mesajului arată schimbări ale detectării/judecății în contexte specifice.'),e('INTERPRETIVE_LINK','Judgment and action remain separable because social motives and incentives can intervene.','Judecata și acțiunea rămân separabile deoarece motivele sociale și stimulentele pot interveni.')],secondary:[{label:{en:'Topic involvement',ro:'Implicare în subiect'},text:{en:'Personal relevance can amplify or redirect emotional effects.',ro:'Relevanța personală poate amplifica sau redirecționa efectele emoționale.'}},{label:{en:'Source authority',ro:'Autoritatea sursei'},text:{en:'Pseudo-authoritative cues can interact with emotional appeal.',ro:'Indiciile pseudo-autoritare pot interacționa cu apelul emoțional.'}}],strongest:{en:'Experimental evidence supports context-specific effects of emotional framing and negative appeal on misinformation detection/sharing, but there is no defensible universal emotion-to-belief estimate.',ro:'Dovezile experimentale susțin efecte specifice contextului ale framing-ului emoțional și apelului negativ asupra detectării/distribuirii misinformation, dar nu există o estimare universală justificabilă emoție→credință.'},uncertainty:{en:'Emotion, salience, novelty and perceived importance are difficult to separate without dedicated measurement.',ro:'Emoția, saliența, noutatea și importanța percepută sunt dificil de separat fără măsurare dedicată.'},moderators:{en:'Message type, topic, personal involvement, source cues and platform context.',ro:'Tipul mesajului, subiectul, implicarea personală, indiciile despre sursă și contextul platformei.'},cannot:{en:'CEM cannot infer an emotional state from clicks, sharing or exposure alone.',ro:'CEM nu poate deduce o stare emoțională numai din click-uri, distribuire sau expunere.'},interventionIds:['accuracy','friction','media-literacy'],theorySlugs:['framing-congruence','processing-metacontrol']},
 {id:'memory-belief',group:'updating',question:{en:'How can memory influence what we believe?',ro:'Cum poate memoria influența ceea ce credem?'},title:{en:'Observed information → memory → world model → belief → judgment',ro:'Informație observată → memorie → world model → credință → judecată'},intro:{en:'Focus on what is retained and retrieved, not merely what was once shown.',ro:'Concentrează-te pe ceea ce este reținut și reactualizat, nu doar pe ceea ce a fost afișat cândva.'},mechanismIds:['observed','memory','world-model','belief','judgment'],edges:[e('EMPIRICAL_ASSOCIATION','Encoding and retrieval connect encountered information to later memory, but exposure alone does not identify retained content.','Encodarea și reactualizarea leagă informația întâlnită de memoria ulterioară, dar expunerea singură nu identifică conținutul reținut.'),e('CONCEPTUAL_HYPOTHESIS','CEM treats remembered information as one input to an internal representation; this bridge is framework-level, not a single measured coefficient.','CEM tratează informația memorată ca una dintre intrările unei reprezentări interne; această punte este la nivel de cadru, nu un coeficient măsurat unic.'),e('INTERPRETIVE_LINK','The internal representation constrains belief judgment but does not determine it uniquely.','Reprezentarea internă constrânge judecata de credință, dar nu o determină unic.'),e('EXECUTABLE_MODEL_RELATION','CEM keeps belief-related state and reported judgment distinct but connected.','CEM păstrează distincte, dar conectate, starea asociată credinței și judecata raportată.')],secondary:[{label:{en:'Source memory',ro:'Memoria sursei'},text:{en:'Remembering where a claim came from can alter later interpretation.',ro:'Reținerea sursei unei afirmații poate modifica interpretarea ulterioară.'}},{label:{en:'Correction memory',ro:'Memoria corecției'},text:{en:'Retrieving a correction can counter residual misinformation effects.',ro:'Reactualizarea unei corecții poate contracara efectele reziduale ale misinformation.'}},{label:{en:'Familiarity',ro:'Familiaritate'},text:{en:'Recognition without source detail can influence truth judgments.',ro:'Recunoașterea fără detalii despre sursă poate influența judecățile de adevăr.'}}],strongest:{en:'Memory-focused reviews show correction durability depends on retrieval, repetition and source memory; later judgments cannot be inferred from exposure history alone.',ro:'Review-urile axate pe memorie arată că durabilitatea corecțiilor depinde de reactualizare, repetare și memoria sursei; judecățile ulterioare nu pot fi deduse numai din istoricul expunerii.'},uncertainty:{en:'Multiple theories—retrieval competition, source monitoring, gist and integrative encoding—can explain overlapping findings.',ro:'Mai multe teorii—competiția la reactualizare, source monitoring, gist și encodarea integrativă—pot explica rezultate suprapuse.'},moderators:{en:'Delay, repetition, correction retrieval, source recollection and task.',ro:'Întârzierea, repetarea, reactualizarea corecției, reținerea sursei și sarcina.'},cannot:{en:'CEM cannot reconstruct what an individual remembers from exposure or click logs.',ro:'CEM nu poate reconstrui ceea ce își amintește un individ din logurile de expunere sau click.'},interventionIds:['debunking','lateral-reading','media-literacy'],theorySlugs:['corrections-accessibility-memory','world-model-construction']},
 {id:'correction-failure',group:'updating',question:{en:'Why can a correction fail or fade?',ro:'De ce poate o corecție să eșueze sau să își piardă efectul?'},title:{en:'Correction → memory → reassessment → belief → judgment',ro:'Corecție → memorie → reevaluare → credință → judecată'},intro:{en:'A correction can be effective without completely erasing the earlier misinformation from reasoning.',ro:'O corecție poate fi eficientă fără a elimina complet misinformation anterioară din raționament.'},mechanismIds:['correction','memory','reassessment','belief','judgment'],edges:[e('EMPIRICAL_CAUSAL_SUPPORT','Corrective information can change memory and belief outcomes in experiments, although durability varies.','Informația corectivă poate schimba memoria și credința în experimente, deși durabilitatea variază.'),e('CONCEPTUAL_HYPOTHESIS','Retrieval of correction and misinformation can trigger revision, but the exact reassessment process is underdetermined.','Reactualizarea corecției și misinformation poate declanșa revizuirea, dar procesul exact de reevaluare este subdeterminat.'),e('EMPIRICAL_ASSOCIATION','Reassessment and belief change covary across correction paradigms, but no universal mapping is justified.','Reevaluarea și schimbarea credinței covariază în paradigmele de corecție, dar nu este justificată o mapare universală.'),e('EXECUTABLE_MODEL_RELATION','CEM keeps updated belief and task-specific judgment separate.','CEM păstrează separate credința actualizată și judecata specifică sarcinii.')],secondary:[{label:{en:'Repeated misinformation',ro:'Misinformation repetată'},text:{en:'Can strengthen familiarity or, under some conditions, support integrative encoding of the correction.',ro:'Poate întări familiaritatea sau, în unele condiții, poate sprijini encodarea integrativă a corecției.'}},{label:{en:'Source memory',ro:'Memoria sursei'},text:{en:'Forgetting where misinformation or correction came from can change durability.',ro:'Uitarea sursei misinformation sau corecției poate schimba durabilitatea.'}},{label:{en:'Delay',ro:'Întârziere'},text:{en:'Corrective influence can weaken over time.',ro:'Influența corectivă poate slăbi în timp.'}}],strongest:{en:'Reviews support debunking as often beneficial while documenting continued-influence effects and time-dependent loss of corrective accessibility.',ro:'Review-urile susțin debunking-ul ca adesea benefic, documentând în același timp continued-influence effects și pierderea în timp a accesibilității corecției.'},uncertainty:{en:'Correction findings differ by domain and outcome; recent science-specific meta-analytic conclusions have also been debated and corrected.',ro:'Rezultatele corecțiilor diferă după domeniu și outcome; concluziile meta-analitice recente specifice misinformation științifice au fost, de asemenea, dezbătute și corectate.'},moderators:{en:'Explanation quality, source, repetition, delay, prior belief and memory for the correction.',ro:'Calitatea explicației, sursa, repetarea, întârzierea, credința anterioară și memoria corecției.'},cannot:{en:'Failure to fully eliminate an effect is not evidence that corrections generally “backfire”.',ro:'Eșecul eliminării complete a unui efect nu este dovadă că corecțiile produc în general „backfire”.'},interventionIds:['debunking','warning','inoculation'],theorySlugs:['corrections-accessibility-memory']},
 {id:'world-model-update',group:'updating',question:{en:'How does new information interact with prior beliefs and update an internal world model?',ro:'Cum interacționează informația nouă cu credințele anterioare și actualizează un model intern al realității?'},title:{en:'Prior knowledge → world model → uncertainty → reassessment → belief',ro:'Cunoaștere anterioară → world model → incertitudine → reevaluare → credință'},intro:{en:'CEM uses world-model language as a representational framework, not as proof that human belief updating is literally Bayesian or predictive-coding computation.',ro:'CEM folosește limbajul world model ca un cadru reprezentațional, nu ca dovadă că actualizarea credințelor umane este literalmente calcul bayesian sau predictive coding.'},mechanismIds:['prior','world-model','uncertainty','reassessment','belief'],edges:[e('CONCEPTUAL_HYPOTHESIS','Prior knowledge constrains the current representation, but CEM does not claim one universal neural implementation.','Cunoașterea anterioară constrânge reprezentarea curentă, dar CEM nu afirmă o implementare neurală universală.'),e('INTERPRETIVE_LINK','Conflicts and missing information can be represented as uncertainty; descriptive uncertainty is not automatically probability.','Conflictele și informația lipsă pot fi reprezentate ca incertitudine; incertitudinea descriptivă nu este automat probabilitate.'),e('CONCEPTUAL_HYPOTHESIS','Uncertainty can motivate reassessment, but this is not inevitable and depends on context/resources.','Incertitudinea poate motiva reevaluarea, dar aceasta nu este inevitabilă și depinde de context/resurse.'),e('INTERPRETIVE_LINK','Reassessment can alter belief, but observed response change does not uniquely identify the internal revision process.','Reevaluarea poate modifica credința, dar schimbarea răspunsului observat nu identifică unic procesul intern de revizuire.')],secondary:[{label:{en:'New observation',ro:'Observație nouă'},text:{en:'New information can enter the representation through separate observation/access stages.',ro:'Informația nouă poate intra în reprezentare prin etape separate de observație/acces.'}},{label:{en:'Source reliability',ro:'Fiabilitatea sursei'},text:{en:'Source cues can change how diagnostic the new information is treated as being.',ro:'Indiciile despre sursă pot schimba cât de diagnostică este tratată informația nouă.'}},{label:{en:'Normative Bayes',ro:'Bayes normativ'},text:{en:'Bayesian updating is a normative operator only when inputs have defensible probabilistic meaning.',ro:'Actualizarea bayesiană este un operator normativ numai când intrările au sens probabilistic justificabil.'}}],strongest:{en:'Research supports memory-, prior- and prediction-dependent perception/cognition broadly, but predictive-processing theories remain heterogeneous and empirically contested at the level of exact neural computations.',ro:'Cercetarea susține în sens larg rolul memoriei, priors și predicției în percepție/cogniție, dar teoriile predictive-processing rămân eterogene și contestate empiric la nivelul calculelor neurale exacte.'},uncertainty:{en:'“World model” is a useful representational abstraction spanning several theories, not one empirically identified human variable.',ro:'„World model” este o abstracție reprezentațională utilă care traversează mai multe teorii, nu o singură variabilă umană identificată empiric.'},moderators:{en:'Task, prior knowledge, evidence quality, memory, uncertainty and resources.',ro:'Sarcina, cunoașterea anterioară, calitatea dovezilor, memoria, incertitudinea și resursele.'},cannot:{en:'CEM cannot reconstruct a person’s complete internal reality model or infer neural predictive coding from behavior.',ro:'CEM nu poate reconstrui modelul intern complet al realității unei persoane și nu poate deduce predictive coding neural din comportament.'},interventionIds:['lateral-reading','media-literacy','debunking'],theorySlugs:['world-model-construction','world-information-representation']},
 {id:'social-norms',group:'action',question:{en:'How can social context and norms influence judgment and sharing?',ro:'Cum pot contextul social și normele influența judecata și distribuirea?'},title:{en:'Social context → appraisal → world model → judgment → action',ro:'Context social → evaluare → world model → judecată → acțiune'},intro:{en:'Track social influence without treating popularity or consensus as truth.',ro:'Urmărește influența socială fără a trata popularitatea sau consensul drept adevăr.'},mechanismIds:['social','appraisal','world-model','judgment','action'],edges:[e('EMPIRICAL_CAUSAL_SUPPORT','Experimental social-norm manipulations can change belief/discernment in tested social-media environments.','Manipulările experimentale ale normelor sociale pot schimba credința/discernământul în mediile social-media testate.'),e('INTERPRETIVE_LINK','Socially informed appraisal can feed the internal representation, but consensus may be dependent or misleading.','Evaluarea informată social poate alimenta reprezentarea internă, dar consensul poate fi dependent sau înșelător.'),e('CONCEPTUAL_HYPOTHESIS','The world model constrains task-specific judgment without a universal social-to-judgment coefficient.','World model-ul constrânge judecata specifică sarcinii fără un coeficient universal social→judecată.'),e('EMPIRICAL_ASSOCIATION','Judgment and sharing are related but can diverge because social motives affect action directly.','Judecata și distribuirea sunt legate, dar pot diverge deoarece motivele sociale afectează direct acțiunea.')],secondary:[{label:{en:'Group identity',ro:'Identitate de grup'},text:{en:'In-group norms can be more influential in some partisan contexts.',ro:'Normele in-group pot fi mai influente în unele contexte partizane.'}},{label:{en:'Consensus independence',ro:'Independența consensului'},text:{en:'Many repeated signals from one source are not equivalent to independent evidence.',ro:'Multe semnale repetate dintr-o singură sursă nu sunt echivalente cu dovezi independente.'}},{label:{en:'Visible engagement',ro:'Engagement vizibil'},text:{en:'Likes and shares can function as social cues as well as exposure mechanisms.',ro:'Like-urile și share-urile pot funcționa ca indicii sociale și mecanisme de expunere.'}}],strongest:{en:'A 2024 simulation experiment (N = 415) found descriptive/injunctive norm messaging improved truth discernment and reduced belief in false claims; some engagement effects were specification-sensitive.',ro:'Un experiment de simulare din 2024 (N = 415) a găsit că mesajele cu norme descriptive/injunctive au îmbunătățit discernământul și au redus credința în afirmații false; unele efecte asupra engagement-ului au fost sensibile la specificația analizei.'},uncertainty:{en:'Single-study and platform-specific evidence should not be treated as a universal norm-to-belief effect.',ro:'Dovezile dintr-un singur studiu și specifice platformei nu trebuie tratate ca un efect universal normă→credință.'},moderators:{en:'Group identity, topic, norm type, perceived independence and platform context.',ro:'Identitatea de grup, subiectul, tipul normei, independența percepută și contextul platformei.'},cannot:{en:'Popularity, consensus and group agreement do not establish factual truth.',ro:'Popularitatea, consensul și acordul de grup nu stabilesc adevărul factual.'},interventionIds:['social-norms','source-labels','friction'],theorySlugs:['algorithms-social-feedback']},
 {id:'belief-to-action',group:'action',question:{en:'Why might someone share something they have not verified?',ro:'De ce poate cineva distribui ceva ce nu a verificat?'},title:{en:'Belief → judgment → accuracy attention → sharing',ro:'Credință → judecată → atenție la acuratețe → distribuire'},intro:{en:'Sharing is a behavior with multiple motives; it is not a direct readout of belief.',ro:'Distribuirea este un comportament cu multiple motive; nu este o citire directă a credinței.'},mechanismIds:['belief','judgment','accuracy-attention','action'],edges:[e('EXECUTABLE_MODEL_RELATION','CEM separates belief-related state from the task-specific decision.','CEM separă starea asociată credinței de decizia specifică sarcinii.'),e('EMPIRICAL_CAUSAL_SUPPORT','Randomized accuracy prompts can alter the decision context and improve sharing discernment.','Accuracy prompts randomizate pot modifica contextul decizional și îmbunătăți discernământul la distribuire.'),e('EMPIRICAL_CAUSAL_SUPPORT','Accuracy-attention interventions reduce false-headline sharing intentions on average in the analyzed experiments.','Intervențiile orientate spre atenția la acuratețe reduc în medie intenția de a distribui titluri false în experimentele analizate.')],secondary:[{label:{en:'Social motives',ro:'Motive sociale'},text:{en:'Identity, signalling, humour or outrage can motivate sharing independently of belief.',ro:'Identitatea, semnalizarea, umorul sau indignarea pot motiva distribuirea independent de credință.'}},{label:{en:'Friction',ro:'Friction'},text:{en:'Adding effort can change whether a sharing intention becomes an action.',ro:'Adăugarea de efort poate modifica dacă intenția de distribuire devine acțiune.'}},{label:{en:'Warning labels',ro:'Warning labels'},text:{en:'Claim-specific labels can alter both belief and sharing in experiments.',ro:'Etichetele specifice afirmației pot modifica atât credința, cât și distribuirea în experimente.'}}],strongest:{en:'Across 20 experiments (N = 26,863), accuracy prompts improved sharing discernment, driven mainly by about a 10% reduction in false-headline sharing intentions.',ro:'În 20 de experimente (N = 26.863), accuracy prompts au îmbunătățit discernământul la distribuire, în principal printr-o reducere de aproximativ 10% a intenției de a distribui titluri false.'},uncertainty:{en:'Sharing intentions are not identical to real-world sharing, and the synthesis comes from one research programme.',ro:'Intențiile de distribuire nu sunt identice cu distribuirea în lumea reală, iar sinteza provine dintr-un singur program de cercetare.'},moderators:{en:'Age, reflection and attention moderated effects in the internal synthesis; ideology, education, gender and race did not robustly do so.',ro:'Vârsta, reflexivitatea și atenția au moderat efectele în sinteza internă; ideologia, educația, genul și rasa nu au făcut-o robust.'},cannot:{en:'Sharing does not prove endorsement, belief, ideology or a stable personal trait.',ro:'Distribuirea nu dovedește aprobarea, credința, ideologia sau o trăsătură personală stabilă.'},interventionIds:['accuracy','warning','friction','social-norms'],theorySlugs:['belief-accuracy-action']},
];

export const pathwayGroups:[ProductPathway['group'],Text][]=[
 ['input',{en:'How information enters and is framed',ro:'Cum intră și este prezentată informația'}],
 ['updating',{en:'How memory and beliefs are updated',ro:'Cum sunt actualizate memoria și credințele'}],
 ['action',{en:'How judgment becomes social action',ro:'Cum devine judecata acțiune socială'}],
];

export const mechanismMap=new Map(mechanisms.map(item=>[item.id,item]));
export const pathwayMap=new Map(pathways.map(item=>[item.id,item]));
export function label(value:Text,language:Language){return value[language];}
